```cs
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using System.Threading.Tasks;

namespace MediumCSharpExample
{
    // Simple Task/Todo management system
    public class TodoItem
    {
        public Guid Id { get; set; } = Guid.NewGuid();
        public string Title { get; set; } = string.Empty;
        public string? Description { get; set; }
        public bool IsCompleted { get; set; }
        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
        public DateTime? DueDate { get; set; }
        public int Priority { get; set; } // 1 = Low, 2 = Medium, 3 = High
    }

    public class TodoManager
    {
        private readonly List<TodoItem> _todos = new();

        public void AddTodo(string title, string? description = null, DateTime? dueDate = null, int priority = 2)
        {
            var todo = new TodoItem
            {
                Title = title,
                Description = description,
                DueDate = dueDate,
                Priority = priority,
                IsCompleted = false
            };

            _todos.Add(todo);
            Console.WriteLine($"✅ Added todo: {title}");
        }

        public void CompleteTodo(Guid id)
        {
            var todo = _todos.FirstOrDefault(t => t.Id == id);
            if (todo != null)
            {
                todo.IsCompleted = true;
                Console.WriteLine($"✅ Completed: {todo.Title}");
            }
            else
            {
                Console.WriteLine("❌ Todo not found.");
            }
        }

        public void ListTodos(bool showCompleted = false)
        {
            var filtered = showCompleted 
                ? _todos 
                : _todos.Where(t => !t.IsCompleted);

            if (!filtered.Any())
            {
                Console.WriteLine("No todos found.");
                return;
            }

            Console.WriteLine("\n📋 Todo List:");
            foreach (var todo in filtered.OrderByDescending(t => t.Priority).ThenBy(t => t.DueDate))
            {
                string status = todo.IsCompleted ? "[✓]" : "[ ]";
                string due = todo.DueDate.HasValue ? $" (Due: {todo.DueDate.Value:yyyy-MM-dd})" : "";
                string prio = todo.Priority switch
                {
                    3 => "🔴",
                    2 => "🟡",
                    _ => "🔵"
                };

                Console.WriteLine($"{status} {prio} {todo.Title}{due}");
                if (!string.IsNullOrEmpty(todo.Description))
                    Console.WriteLine($"   └─ {todo.Description}");
            }
        }

        public void RemoveTodo(Guid id)
        {
            var todo = _todos.FirstOrDefault(t => t.Id == id);
            if (todo != null)
            {
                _todos.Remove(todo);
                Console.WriteLine($"🗑️  Removed: {todo.Title}");
            }
        }

        public string ExportToJson()
        {
            return JsonSerializer.Serialize(_todos, new JsonSerializerOptions
            {
                WriteIndented = true
            });
        }

        public async Task ImportFromJsonAsync(string json)
        {
            try
            {
                var imported = JsonSerializer.Deserialize<List<TodoItem>>(json);
                if (imported != null)
                {
                    _todos.Clear();
                    _todos.AddRange(imported);
                    Console.WriteLine($"📥 Imported {imported.Count} todos.");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"❌ Import failed: {ex.Message}");
            }
        }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            Console.WriteLine("🚀 Medium C# Todo Manager");
            Console.WriteLine("==========================\n");

            var manager = new TodoManager();

            // Demo data
            manager.AddTodo("Finish C# project", "Implement JSON export/import", DateTime.UtcNow.AddDays(2), 3);
            manager.AddTodo("Buy groceries", null, DateTime.UtcNow.AddDays(1), 2);
            manager.AddTodo("Read documentation", "Review System.Text.Json", null, 1);

            manager.ListTodos();

            Console.WriteLine("\nMarking first todo as complete...");
            // In real app you would get ID from user input
            var firstId = manager.GetType().GetField("_todos", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)
                ?.GetValue(manager) as List<TodoItem>?.FirstOrDefault()?.Id ?? Guid.Empty;
            if (firstId != Guid.Empty)
                manager.CompleteTodo(firstId);

            manager.ListTodos();

            // Export example
            string json = manager.ExportToJson();
            Console.WriteLine("\n📤 Exported JSON:");
            Console.WriteLine(json.Substring(0, Math.Min(300, json.Length)) + "...");

            Console.WriteLine("\n✅ Demo completed. Ready for extension!");
        }
    }
}
